class ControlService {
  private readonly config: ReturnType<typeof loadControlServerConfig>;
  private readonly repository: RevisionRepository;
  private readonly artifacts: ContentAddressedArtifactStore;
  private readonly pool: Database;

  constructor(pool: Database, environment?: NodeJS.ProcessEnv) {
    this.config = loadControlServerConfig(environment);
    this.pool = pool;
    this.repository = new RevisionRepository(pool);
    this.artifacts = new ContentAddressedArtifactStore(this.config.artifactRoot);
  }

private authenticated(request: IncomingMessage): {
  user: string;
  roles: string[];
  csrf: string;
} {
  const {sessionSecret} = this.config;
  const values = cookies(request);
  const session = verifySession(values.prism_session ?? "", sessionSecret);
  const csrf = values.prism_csrf ?? "";
  if (
    !["GET", "HEAD"].includes(request.method ?? "") &&
    (!csrf || request.headers["x-prism-csrf"] !== csrf)
